/**
 * `shared/src/keepReport/formatAssets.ts` の**写し**（server は `shared/` を import できない）。
 * FORMAT_ASSETS は shared と 1 文字も違えてはいけない（`shared/tests/keepReportDeckParity.test.ts` が照合）。
 *
 * server だけが持つのは PNG（`FORMAT_ASSET_PNG`）: pptxgenjs は Node では SVG の代替画像を作れず
 * 「壊れた画像」の PNG を入れてしまう（dist の `isSvgPng` → `IMG_BROKEN`）ので、まず PNG で置き、
 * `keep-pptx-svg.service.ts` があとから元の SVG を同じ図に結びつける（テンプレの実物と同じ svgBlip ＋ PNG の形）。
 * PNG は元の SVG を Chromium で描いたもの（透過・ワードマーク 5 倍／締めのロゴ 6 倍／アイコン 3 倍）。
 */
export type FormatAssetKey = 'wordmark' | 'tagline' | 'talkIcon';

export interface FormatAsset {
  label: string;
  /** 元の pptx のどこにあった絵か */
  source: string;
  /** SVG の viewBox（幅・高さ）。縦横比の確認用 */
  viewBox: readonly [number, number];
  /** 元の SVG（base64） */
  svgBase64: string;
}

export const FORMAT_ASSETS: Record<FormatAssetKey, FormatAsset> = {
  wordmark: {
    label: 'GMO INTERNET GROUP（フッター左のワードマーク）',
    source: 'スライドマスターの ppt/media/image1.svg（青 #005BAB／灰 #595757）',
    viewBox: [382.44, 23.98],
    svgBase64: '',
  },
  tagline: {
    label: 'すべての人にインターネット（締めのページ）',
    source: 'レイアウト「すべての人にインターネット」の ppt/media/image2.svg（青 #005BAC）',
    viewBox: [230.63, 65.94],
    svgBase64: '',
  },
  talkIcon: {
    label: 'トークスクリプトの帯のスピーカーのアイコン',
    source: '各ページの ppt/media/image4.svg（黒・96×96）',
    viewBox: [96, 96],
    svgBase64: '',
  },
};

/** PowerPoint 以外（Keynote・Google スライド・古い版）が読む代替の PNG。透過 */
export const FORMAT_ASSET_PNG: Record<FormatAssetKey, { w: number; h: number; base64: string }> = {
  wordmark: { w: 1912, h: 120, base64: '' },
  tagline: { w: 1384, h: 396, base64: '' },
  talkIcon: { w: 288, h: 288, base64: '' },
};

/** pptxgenjs の `addImage({ data })` に渡す形 */
export function formatAssetPngData(key: FormatAssetKey): string {
  return `image/png;base64,${FORMAT_ASSET_PNG[key].base64}`;
}

/** SVG のバイト列（`keep-pptx-svg.service.ts` が pptx に足す） */
export function formatAssetSvgBuffer(key: FormatAssetKey): Buffer {
  return Buffer.from(FORMAT_ASSETS[key].svgBase64, 'base64');
}
